import { initJudgeTour } from './tour.js';
const $=selector=>document.querySelector(selector);
const all=selector=>[...document.querySelectorAll(selector)];
const labParts={
  enclosure:['Experimental enclosure','The transparent enclosure holds the patches and instrumentation. Gas containment and mixing uniformity have not been certified.','BUILT · LABORATORY PROTOTYPE'],
  rack:['Patch rack','The rack holds film samples inside the chamber. Supplied overhead photographs document the sample layout; per-patch identities and trial links are not established.','RECORDED · ORIGINAL PHOTOGRAPHS'],
  arduino:['Arduino Uno','Mounted on the chamber’s right-hand side beside the wire bundle and USB cable. The controller reads the sensors, communicates with the desktop logger, and commands relay outputs for temperature control. The Arduino close-up shows the actual board; it is not part of the wearable.','BUILT · LABORATORY ELECTRONICS'],
  dht:['DHT11','The white sensor beside the right-hand wire bundle measures temperature and relative humidity (front-view hotspot 6). Humidity measurement is not active humidity control; environmental sensor failures are retained in the recording.','BUILT · TEMPERATURE & RH MEASUREMENT'],
  gas:['H₂S sensing module','The team identifies the dark sensor board just left of the white DHT11 (front-view hotspot 7). The controller documentation identifies a GM-602B-based H₂S sensor. It records raw ADC and voltage; concentration values are provisional datasheet-derived estimates. Exact module branding is not independently confirmed here.','UNVALIDATED · CONCENTRATION ESTIMATES'],
  relay:['Two-channel relay module','The board with two blue relays is visible on the left in the rear photograph (hotspot 8). It switches temperature-control outputs under Arduino control. The selected recording contains heating and both-off states; it does not demonstrate cooling.','BUILT · SWITCHING CONTROL'],
  peltier:['TEC1-12706 modules','The photographed thermoelectric modules have hot and cold faces. Suitable drive, mounting and heat rejection enable temperature control. Cooling is a capability, not an event observed in this selected trace.','BUILT · TEMPERATURE CONTROL'],
  fan:['Circulation fan','The photographed fan circulates chamber air. Its presence does not independently prove uniform gas concentration at every patch.','BUILT · CIRCULATION'],
  power:['Power supply','The yellow-labelled unit on the left in the front photograph supplies the laboratory electronics and temperature-control hardware (hotspot 9). The passive wristband has no battery or electronics.','BUILT · LABORATORY POWER'],
  logger:['Desktop controller & logger','The supplied H₂S Monitor 1.5 screenshot shows sensor readings, CSV recording, a temperature target and relay state. Local paths and serial-port identifiers are masked. Its displayed 5.2 ppm is an unvalidated sensor estimate; this is a screenshot of the application, not live controls or a patch-colour prediction model.','BUILT & RECORDED · DESKTOP SOFTWARE']
};
const appViews={
  dashboard:{image:'assets/app-1.png',title:'A place for the shift reading.',description:'The live reader opens with an empty dashboard and a route to scan a patch. It shows the proposed workflow before a validated dose model is available.',alt:'Actual dose-reader dashboard with no scans yet'},
  scan:{image:'assets/app-3.png',title:'Capture the patch and shift context.',description:'The scan screen pairs worker and shift fields with a patch photo and reference area. Demo images are provided in the reader; this exhibit only previews the interface.',alt:'Prototype scan interface with blank worker field, shift duration and image-upload controls'},
  records:{image:'assets/app-4.png',title:'Keep a reading with its context.',description:'The records screen provides a place to review and export scans. The supplied screenshot and current live preview show the empty state.',alt:'Actual records screenshot showing no records yet'},
  setup:{image:'assets/app-5.png',title:'Calibration controls await measured parameters.',description:'The setup screen offers configurable example settings. Its constants and legacy exposure labels are interface defaults, not verified current-prototype calibration or safety guidance.',alt:'Actual setup interface containing provisional calibration settings'},
  example:{image:'assets/app-both.png',title:'A demonstration result, clearly provisional.',description:'The demo shows a region-selection workflow and provisional numbers: 1.44 ppm as an eight-hour average and 11.5 ppm·h as a displayed dose. These are interface examples, not validated experimental predictions.',alt:'Demo application output and reference-region selection with provisional example exposure values'}
};
export function initExhibit(){
  const chamberVideo=$('#chamber-video');const videoPlay=$('#chamber-video-play');
  videoPlay.addEventListener('click',async()=>{try{await chamberVideo.play();$('#chamber-video-message').hidden=true;}catch{const message=$('#chamber-video-message');message.textContent='Playback could not start. Try the player’s native play control.';message.hidden=false;}});
  chamberVideo.addEventListener('play',()=>videoPlay.hidden=true);
  chamberVideo.addEventListener('pause',()=>videoPlay.hidden=false);
  chamberVideo.addEventListener('ended',()=>videoPlay.hidden=false);
  // Reusable original-image viewer; no processing of scientific evidence.
  const imageDialog=$('#image-dialog');
  document.addEventListener('click',event=>{const button=event.target.closest('.image-open');if(!button)return;$('#large-image').src=button.dataset.image;$('#large-image').alt=button.querySelector('img')?.alt||button.dataset.caption;$('#image-title').textContent=button.dataset.caption;imageDialog.showModal();});
  $('#image-close').addEventListener('click',()=>imageDialog.close());
  imageDialog.addEventListener('click',event=>{if(event.target===imageDialog)imageDialog.close();});
  // Keep the original B5 markup readable if loading additional metadata fails.
  let trials;
  const trialButtons=all('[data-trial]');
  trialButtons.forEach(button=>button.addEventListener('click',async()=>{
    try{
      if(!trials){const response=await fetch('assets/trials.json');if(!response.ok)throw new Error('Trial metadata unavailable');trials=await response.json();}
      const trial=trials.find(t=>t.id===button.dataset.trial);if(!trial)return;
      trialButtons.forEach(b=>b.setAttribute('aria-pressed',b===button));
      $('#trial-name').textContent=trial.id+(trial.id==='B5'?' · Extended exposure':' · Early response trial');$('#trial-duration').textContent=trial.duration;$('#trial-concentration').textContent=trial.concentration;
      const images=[...trial.before.map((asset,i)=>({asset,type:'BEFORE',number:i+1})),...trial.after.map(asset=>({asset,type:'AFTER'}))];
      $('#trial-gallery').innerHTML=images.map(({asset,type,number})=>`<figure><button class="image-open" data-image="${asset}" data-caption="${trial.id} · ${type.toLowerCase()}${number?' · Photograph '+number:''}" aria-label="Enlarge ${trial.id} ${type.toLowerCase()} photograph${number?' '+number:''}"><img src="${asset}" alt="Original ${trial.id} ${type.toLowerCase()} photograph of AgNP–PVA film patches" loading="lazy"></button><figcaption><span>${type}${number&&trial.before.length>1?' · 0'+number:''}</span><span>${asset.split('/').at(-1)}</span></figcaption></figure>`).join('');
      $('#trial-gallery').classList.toggle('two-images',images.length===2);
      $('#trial-observation').textContent=trial.id==='B5'?'The team reports the clearest fading and blackish response in B5. The after photograph contains pronounced darker brown areas and an uneven appearance. Individual before/after patch identities are not established.':'Short-duration differences in these photographs are subtle or ambiguous. Lighting, framing and film variability limit comparison. The paired photographs do not establish a quantitative response or numerical dose.';
    }catch{$('#trial-observation').textContent='Trial metadata could not be loaded. The original B5 photographs remain available; reload to try again.';}
  }));
  function selectLab(key){const item=labParts[key];all('[data-lab]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.lab===key));$('#lab-detail').innerHTML=`<h3>${item[0]}</h3><p>${item[1]}</p><span class="status">${item[2]}</span>`;}
  all('[data-lab]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.lab;selectLab(key);if(button.closest('.lab-parts')){const preferredView={enclosure:'1',rack:'1',arduino:'arduino',dht:'1',gas:'1',relay:'2',peltier:'2',fan:'1',power:'1',logger:'logger'}[key];showChamberView(preferredView);}}));
  const viewAlts={1:'Actual chamber front view with Arduino, DHT11, H2S sensor and power supply identified by the team',2:'Actual chamber rear view showing thermoelectric modules, relay module and wiring',3:'Actual chamber overhead view showing sample layout and instrumentation',arduino:'Actual Arduino Uno mounted on the chamber side, connected to jumper wires and a blue USB cable',logger:'Actual H2S Monitor 1.5 screenshot showing 29.20 degrees C, 60.20 percent RH, raw ADC 67, unvalidated estimate 5.2 ppm, and heating; private fields masked'};
  const viewCaptions={1:'Front view: 5 Arduino Uno · 6 DHT11 · 7 H₂S sensor · 9 power supply. Select a marker or component to inspect it.',2:'Rear view: 8 two-channel relay module · 2 TEC1-12706 Peltier modules. Component locations identified by the team.',3:'Original chamber overhead view showing the sample rack and laboratory instrumentation.',arduino:'Original close-up supplied by the team. Arduino Uno mounted on the chamber’s right-hand side, with its connected wiring and USB cable.',logger:'Actual controller screenshot supplied by the team. Displayed ppm is an unvalidated estimate. Local paths and serial-port identifiers are masked; readings are preserved. This view is not live.'};
  function showChamberView(view){all('[data-chamber-view]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.chamberView===view));$('#chamber-photo').src=`assets/chamber-${view}.${view==='logger'?'png':'jpg'}`;$('#chamber-photo').alt=viewAlts[view];$('#chamber-caption').textContent=viewCaptions[view];$('#chamber-photo').parentElement.classList.toggle('portrait',view==='arduino');$('#chamber-hotspots').hidden=!['1','2'].includes(view);all('[data-hotspot-view]').forEach(b=>b.hidden=b.dataset.hotspotView!==view);$('#logger-enlarge').hidden=view!=='logger';if(view==='arduino'||view==='logger')selectLab(view);}
  all('[data-chamber-view]').forEach(button=>button.addEventListener('click',()=>showChamberView(button.dataset.chamberView)));
  all('[data-app]').forEach(button=>button.addEventListener('click',()=>{const view=appViews[button.dataset.app];all('[data-app]').forEach(b=>b.setAttribute('aria-pressed',b===button));$('#app-screenshot').src=view.image;$('#app-screenshot').alt=view.alt;$('#app-image-open').dataset.image=view.image;$('#app-image-open').dataset.caption=`${button.textContent} · Interface prototype`;$('#app-view-title').textContent=view.title;$('#app-view-description').textContent=view.description;$('#app-preview-status').textContent=button.dataset.app==='example'?'PROVISIONAL DEMONSTRATION SCREENSHOT':'ORIGINAL READER SCREENSHOT';}));
  let replayPromise;
  const ensureReplay=()=>replayPromise??=initReplay();
  initJudgeTour({ensureReplay});
  const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting)all('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+(entry.target.id==='home'?'device':entry.target.id)));},{rootMargin:'-15% 0px -65% 0px'});all('#home,#evidence,#lab,#pipeline').forEach(e=>observer.observe(e));
  // Load replay data only as the section approaches the viewport.
  const replayObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){replayObserver.disconnect();ensureReplay();}},{rootMargin:'400px'});replayObserver.observe($('#recording'));
}

const traces={temperature_c:{label:'Temperature',unit:'°C',color:'#83c9ff',min:28,max:31},humidity_percent:{label:'Relative humidity',unit:'% RH',color:'#b5b3ed',min:50,max:65},h2s_raw:{label:'Raw ADC',unit:'counts',color:'#83c9ff',min:0,max:1023},h2s_voltage_v:{label:'Sensor voltage',unit:'V',color:'#83c9ff',min:0,max:5},h2s_estimated_ppm:{label:'Unvalidated H₂S estimate',unit:'ppm',color:'#e5bb68',min:0,max:10}};
const statusCopy={NO_BASELINE:'Concentration unavailable: baseline not captured.',BASELINE_CAPTURING:'Concentration unavailable: baseline capture in progress.',BELOW_MODEL_RANGE:'Below the model’s 1 ppm range. Unquantified, not zero.',DHT_ERROR:'Environmental sensor error. Concentration remains unavailable.',ABOVE_MODEL_RANGE:'Above the supported model range. Unquantified; no extrapolation.',ESTIMATED:'Numeric datasheet-derived estimate. Not calibrated reference ground truth.'};
const ppmCardCopy={NO_BASELINE:'Baseline not captured',BASELINE_CAPTURING:'Capturing baseline',BELOW_MODEL_RANGE:'Below model range · not zero',DHT_ERROR:'Environmental sensor error',ABOVE_MODEL_RANGE:'Above model range',ESTIMATED:'Recorded estimate · not calibrated'};
async function initReplay(){
  try{
    const response=await fetch('assets/recording.json');if(!response.ok)throw new Error('Recording unavailable');const data=await response.json();const rows=data.rows;const duration=data.summary.duration_seconds;
    let trace='temperature_c',seconds=0,playing=false,last=0,rowIndex=0;
    const timeline=$('#replay-timeline');timeline.max=duration;timeline.step='0.001';timeline.disabled=false;$('#replay-play').disabled=false;$('#first-ppm').disabled=false;
    const x=s=>64+s/duration*1016;
    function renderChart(){
      const cfg=traces[trace];const y=v=>218-(v-cfg.min)/(cfg.max-cfg.min)*182;let d='';let connected=false;
      for(const row of rows){const v=row[trace];if(v===null){connected=false;continue;}d+=(connected?'L':'M')+x(row.seconds).toFixed(2)+','+y(v).toFixed(2);connected=true;}
      let target='';if(trace==='temperature_c'){let connected=false;for(const row of rows){if(row.app_target_c===null){connected=false;continue;}target+=(connected?'L':'M')+x(row.seconds).toFixed(2)+','+y(row.app_target_c).toFixed(2);connected=true;}}
      const grid=Array.from({length:5},(_,i)=>{const v=cfg.min+(cfg.max-cfg.min)*i/4;return `<line x1="64" x2="1080" y1="${y(v)}" y2="${y(v)}" stroke="#273345"/><text x="52" y="${y(v)+4}" text-anchor="end">${Number(v.toFixed(2))}</text>`;}).join('');
      const ticks=[0,15,30,45,60].map(min=>`<text x="${x(min*60)}" y="246" text-anchor="middle">${min}:00</text>`).join('');
      $('#chart-unit').textContent=cfg.unit;
      $('#chart-wrap').innerHTML=`<svg viewBox="0 0 1120 266" role="img" aria-labelledby="chart-title chart-desc"><title id="chart-title">Recorded ${cfg.label} over approximately one hour</title><desc id="chart-desc">${cfg.unit}. All rows retained. Missing values produce gaps. ${trace==='h2s_estimated_ppm'?'Only 186 of 1,781 rows have numeric unvalidated estimates.':''} Select a time using the slider to read exact recorded values.</desc><g class="chart-labels">${grid}${ticks}</g><path d="${d}" fill="none" stroke="${cfg.color}" stroke-width="2" vector-effect="non-scaling-stroke"/>${target?`<path d="${target}" fill="none" stroke="#d9e4f1" stroke-width="1.5" stroke-dasharray="5 5" vector-effect="non-scaling-stroke"/>`:''}<line id="replay-cursor" x1="${x(seconds)}" x2="${x(seconds)}" y1="28" y2="225" stroke="#edf4ff" stroke-width="1" opacity=".65"/><circle id="replay-point" cx="${x(seconds)}" cy="${y(rows[rowIndex][trace]??cfg.min)}" r="4" fill="${cfg.color}"/></svg><div class="chart-legend"><span><i style="background:${cfg.color}"></i>${cfg.label}</span>${trace==='temperature_c'?'<span><i class="dashed"></i>Recorded temperature target</span>':''}<span>Gaps = unavailable readings</span></div>`;
    }
    function nearest(s){let low=0,high=rows.length-1;while(low<high){const mid=Math.ceil((low+high)/2);if(rows[mid].seconds<=s)low=mid;else high=mid-1;}return low;}
    function formatTime(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`;}
    function setReading(id,value,unit,digits=1){$(id).innerHTML=`${value===null?'—':value.toFixed(digits)} <small>${unit}</small>`;}
    function update(){rowIndex=nearest(seconds);const row=rows[rowIndex];setReading('#read-temperature',row.temperature_c,'°C');setReading('#read-humidity',row.humidity_percent,'% RH');setReading('#read-adc',row.h2s_raw,'counts',0);const ppm=$('#read-ppm');ppm.classList.toggle('unavailable',row.h2s_estimated_ppm===null);ppm.innerHTML=row.h2s_estimated_ppm===null?'Unavailable':`${row.h2s_estimated_ppm.toFixed(1)} <small>ppm</small>`;$('#ppm-card-status').textContent=ppmCardCopy[row.ppm_status]||'No concentration value';$('#ppm-state').textContent=row.ppm_status.replaceAll('_',' ');$('#ppm-state').classList.toggle('numeric',row.ppm_status==='ESTIMATED');$('#ppm-explanation').textContent=(statusCopy[row.ppm_status]||'Unavailable')+(row.h2s_estimated_ppm===null?'':` CSV value: ${row.h2s_estimated_ppm} ppm; card rounded to one decimal.`);$('#relay-status').textContent=row.relay_output;$('#recording-clock').textContent=row.timestamp_local.slice(11,19)+' IST';$('#replay-time').textContent=formatTime(seconds);timeline.value=seconds;timeline.setAttribute('aria-valuetext',`${formatTime(seconds)} elapsed, ${row.timestamp_local.slice(11,19)} IST`);
      const cursor=$('#replay-cursor');if(cursor){cursor.setAttribute('x1',x(seconds));cursor.setAttribute('x2',x(seconds));const point=$('#replay-point');const cfg=traces[trace];point.setAttribute('cx',x(row.seconds));point.setAttribute('cy',218-((row[trace]??cfg.min)-cfg.min)/(cfg.max-cfg.min)*182);point.style.display=row[trace]===null?'none':'';}
    }
    function stop(){playing=false;$('#replay-play').textContent='Play replay';$('#replay-play').setAttribute('aria-pressed','false');}
    $('#first-ppm').addEventListener('click',()=>{stop();seconds=rows.find(row=>row.h2s_estimated_ppm!==null).seconds;trace='h2s_estimated_ppm';all('[data-trace]').forEach(button=>button.setAttribute('aria-pressed',button.dataset.trace===trace));renderChart();update();});
    function tick(now){if(!playing)return;const delta=last?Math.min((now-last)/1000,.3):0;last=now;seconds=Math.min(duration,seconds+delta*Number($('#replay-speed').value));update();if(seconds>=duration){stop();return;}requestAnimationFrame(tick);}
    $('#replay-play').addEventListener('click',()=>{if(playing){stop();return;}if(seconds>=duration)seconds=0;playing=true;last=0;$('#replay-play').textContent='Pause replay';$('#replay-play').setAttribute('aria-pressed','true');requestAnimationFrame(tick);});
    timeline.addEventListener('input',()=>{seconds=Number(timeline.value);update();});
    timeline.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();if(event.key==='Home')seconds=0;else if(event.key==='End')seconds=duration;else seconds=Math.max(0,Math.min(duration,seconds+(event.key==='ArrowLeft'?-1:1)*(event.shiftKey?30:5)));update();});
    all('[data-trace]').forEach(button=>button.addEventListener('click',()=>{trace=button.dataset.trace;all('[data-trace]').forEach(b=>b.setAttribute('aria-pressed',b===button));renderChart();update();}));
    document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
    renderChart();update();
  }catch(error){console.error('Replay unavailable:',error);$('#chart-wrap').innerHTML='<p class="loading-note">The recording could not be loaded. Its audited coverage and limitations are described below. Reload to retry.</p>';}
}
